@php($editing=isset($receipt))<x-app-layout :title="$editing ? 'Edit Cash Receipt' : 'Record Cash Receipt'"><x-page-header :title="$editing ? 'Edit Cash Receipt' : 'Record Cash Receipt'" description="Save a draft before posting it to an operational account."/><form method="POST" action="{{ $editing ? route('cash-receipts.update',$receipt) : route('cash-receipts.store') }}" class="grid gap-5 rounded-2xl bg-white p-6 ring-1 ring-slate-200 md:grid-cols-2">@csrf @if($editing)@method('PUT')@endif @foreach(['receipt_date'=>'Receipt date'] as $field=>$label)<label class="grid gap-1 text-sm">{{ $label }}<input type="date" name="{{ $field }}" value="{{ old($field,isset($receipt)?$receipt->{$field}->toDateString():now()->toDateString()) }}" required class="rounded-lg border-slate-300">@error($field)<span class="text-red-600">{{ $message }}</span>@enderror</label>@endforeach<label class="grid gap-1 text-sm">Fiscal period<select name="fiscal_period_id" required class="rounded-lg border-slate-300"><option value="">Select period</option>@foreach($periods as $period)<option value="{{ $period->id }}" @selected(old('fiscal_period_id',$receipt->fiscal_period_id??'')==$period->id)>{{ $period->name }}</option>@endforeach</select>@error('fiscal_period_id')<span class="text-red-600">{{ $message }}</span>@enderror</label><label class="grid gap-1 text-sm">Financial account<select name="financial_account_id" required class="rounded-lg border-slate-300"><option value="">Select account</option>@foreach($accounts as $account)<option value="{{ $account->id }}" @selected(old('financial_account_id',$receipt->financial_account_id??'')==$account->id)>{{ $account->code }} — {{ $account->name }}</option>@endforeach</select>@error('financial_account_id')<span class="text-red-600">{{ $message }}</span>@enderror</label><label class="grid gap-1 text-sm">Source type<select name="source_type" required class="rounded-lg border-slate-300">@foreach($sourceTypes as $type)<option value="{{ $type->value }}" @selected(old('source_type',$receipt->source_type->value??'')===$type->value)>{{ str($type->value)->headline() }}</option>@endforeach</select>@error('source_type')<span class="text-red-600">{{ $message }}</span>@enderror</label><label class="grid gap-1 text-sm">Customer (when applicable)<select name="customer_id" class="rounded-lg border-slate-300"><option value="">None</option>@foreach($customers as $customer)<option value="{{ $customer->id }}" @selected(old('customer_id',$receipt->customer_id??'')==$customer->id)>{{ $customer->name }}</option>@endforeach</select></label><label class="grid gap-1 text-sm">Customer payment (when applicable)<select name="customer_payment_id" class="rounded-lg border-slate-300"><option value="">None</option>@foreach($payments as $payment)<option value="{{ $payment->id }}" @selected(old('customer_payment_id',$receipt->customer_payment_id??'')==$payment->id)>{{ $payment->payment_number }} — {{ $payment->customer->name ?? 'Customer' }} — PHP {{ number_format((float)$payment->net_cash_received,2) }}</option>@endforeach</select>@error('customer_payment_id')<span class="text-red-600">{{ $message }}</span>@enderror</label><label class="grid gap-1 text-sm">Payer name<input name="payer_name" value="{{ old('payer_name',$receipt->payer_name??'') }}" required class="rounded-lg border-slate-300">@error('payer_name')<span class="text-red-600">{{ $message }}</span>@enderror</label><label class="grid gap-1 text-sm">Payment method<select name="payment_method_id" required class="rounded-lg border-slate-300">@foreach($paymentMethods as $method)<option value="{{ $method->id }}" @selected(old('payment_method_id',$receipt->payment_method_id??'')==$method->id)>{{ $method->name }}</option>@endforeach</select></label><label class="grid gap-1 text-sm">Bank/e-wallet reference<input name="reference_number" value="{{ old('reference_number',$receipt->reference_number??'') }}" class="rounded-lg border-slate-300"></label>@foreach(['gross_receipt'=>'Gross receipt','deductions_or_fees'=>'Deductions or fees','net_amount_deposited'=>'Net amount deposited'] as $field=>$label)<label class="grid gap-1 text-sm">{{ $label }}<input type="number" step="0.0001" min="0" name="{{ $field }}" value="{{ old($field,$receipt->{$field}??'0.0000') }}" required class="rounded-lg border-slate-300">@error($field)<span class="text-red-600">{{ $message }}</span>@enderror</label>@endforeach<label class="grid gap-1 text-sm md:col-span-2">Notes<textarea name="notes" rows="3" class="rounded-lg border-slate-300">{{ old('notes',$receipt->notes??'') }}</textarea></label><button class="w-fit rounded-lg bg-blue-700 px-4 py-2 font-semibold text-white">Save draft</button></form></x-app-layout>
